const DEFAULT_MAX_TURNS=20,REFERENCE_WORDS=["there","it","that place","this place","that","this"];function buildReferencePattern(){const t=REFERENCE_WORDS.slice().sort((t,e)=>e.length-t.length).map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"));return new RegExp(`\\b(${t.join("|")})\\b`,"gi")}export class ConversationContext{constructor(t={}){this.maxTurns=t.maxTurns||20,this.turns=[],this.lastEntity=null,this.lastIntent=null}resolveReferences(t){if(!this.lastEntity||!this.lastEntity.name)return t;const e=buildReferencePattern();return e.test(t)?(e.lastIndex=0,t.replace(e,this.lastEntity.name)):t}remember({speaker:t,text:e,intent:n,entity:s}){this.turns.push({speaker:t,text:e,intent:n,entity:s,timestamp:Date.now()}),this.turns.length>this.maxTurns&&this.turns.shift(),s&&s.name&&(this.lastEntity=s),n&&(this.lastIntent=n)}getHistory(){return this.turns.slice()}getLastEntity(){return this.lastEntity}reset(){this.turns=[],this.lastEntity=null,this.lastIntent=null}}export default ConversationContext;